package org.marketreview.nativeapp;
import org.json.*;
import java.io.*;
import java.util.*;
import java.security.MessageDigest;
final class ArchiveVideoReviewModel {
 static String canonical(Object value) throws JSONException {if(value instanceof JSONObject){JSONObject o=(JSONObject)value;ArrayList<String>keys=new ArrayList<>();Iterator<String>i=o.keys();while(i.hasNext())keys.add(i.next());Collections.sort(keys);StringBuilder b=new StringBuilder("{");for(String k:keys)b.append(JSONObject.quote(k)).append(':').append(canonical(o.get(k))).append(',');return b.append('}').toString();}if(value instanceof JSONArray){StringBuilder b=new StringBuilder("[");JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++)b.append(canonical(a.get(i))).append(',');return b.append(']').toString();}if(value instanceof Number)return JSONObject.numberToString((Number)value);return value instanceof String?JSONObject.quote((String)value):String.valueOf(value);}
 static double seekSeconds(JSONObject segment,double duration){Object a=segment.opt("start"),b=segment.opt("end");if(!(a instanceof Number)||!(b instanceof Number)||!Double.isFinite(duration)||duration<=0)return -1;double start=((Number)a).doubleValue(),end=((Number)b).doubleValue();return Double.isFinite(start)&&Double.isFinite(end)&&start>=0&&end>=start&&end<=duration?start:-1;}
 static JSONObject inspect(JSONObject row,JSONObject current,List<File>roots){JSONObject out=new JSONObject();try{out.put("playable",false).put("linkageVerified",false);if(!(row.opt("id") instanceof String)||row.optString("id").isEmpty()||current==null||!canonical(row).equals(canonical(current)))return fail(out,"作品记录版本已改变或缺少身份，请重新打开");JSONObject archive=row.optJSONObject("archive");String path=row.optString("assetPath"),sha=archive==null?"":archive.optString("sha256");Object n=archive==null?null:archive.opt("bytes");double bytes=n instanceof Number?((Number)n).doubleValue():-1;if(archive==null||path.isEmpty()||!path.equals(archive.optString("assetPath"))||!sha.matches("(?i)[0-9a-f]{64}")||bytes<=0||bytes>256.0*1024*1024||bytes!=Math.floor(bytes))return fail(out,"缺少有效的媒体归档路径、字节数或 SHA256 证据");File raw=new File(path),file=raw.getCanonicalFile();if(!raw.isAbsolute()||path.contains("://")||path.startsWith("//")||path.startsWith("\\\\")||!file.isFile())return fail(out,"只允许存在的本机归档普通文件");boolean allowed=false;for(File root:roots){File r=root.getCanonicalFile();if(r.isDirectory()&&file.getPath().startsWith(r.getPath()+File.separator))allowed=true;}if(!allowed)return fail(out,"文件不在允许的媒体归档目录中");long modified=file.lastModified();if(file.length()!=(long)bytes)return fail(out,"归档字节数不一致");MessageDigest hash=MessageDigest.getInstance("SHA-256");long read=0;try(InputStream input=new FileInputStream(file)){byte[]buffer=new byte[65536];int count;while((count=input.read(buffer))!=-1){hash.update(buffer,0,count);read+=count;if(read>256L*1024*1024)return fail(out,"归档超过允许大小");}}StringBuilder actual=new StringBuilder();for(byte x:hash.digest())actual.append(String.format(Locale.ROOT,"%02x",x&255));if(!actual.toString().equalsIgnoreCase(sha)||read!=(long)bytes||file.length()!=read||file.lastModified()!=modified)return fail(out,"归档 SHA256 不匹配或核验时文件改变");return out.put("playable",true).put("path",file.getPath()).put("reason","归档已核验；逐字稿与媒体对应关系未自动核验");}catch(Exception e){return fail(out,"归档只读核验失败："+e.getClass().getSimpleName());}}
 private static JSONObject fail(JSONObject out,String reason){try{return out.put("reason",reason);}catch(JSONException e){throw new IllegalStateException(e);}}
}


